"""Data contracts for structured AI drafts and candidate claims."""

from typing import List, Optional
from pydantic import BaseModel, ConfigDict, Field

from backend.app.schemas.explanation import ClaimType


class AICandidateClaim(BaseModel):
    """An atomic candidate assertion generated by an LLM with proposed evidence citations."""
    model_config = ConfigDict(extra="forbid", frozen=True)

    claim_id: str = Field(..., min_length=1, description="Local draft identifier (e.g. 'claim_1').")
    claim_type: ClaimType = Field(..., description="Classification of assertion.")
    text: str = Field(..., min_length=3, max_length=512, description="Proposed natural language statement.")
    cited_fact_ids: List[str] = Field(
        default_factory=list,
        description="IDs of atomic EvidenceFacts cited to substantiate this claim.",
    )
    cited_knowledge_ids: List[str] = Field(
        default_factory=list,
        description="IDs of Qdrant RetrievedPassages cited for background context.",
    )
    claimed_runs: Optional[int] = Field(default=None, description="Explicit runs mentioned in the assertion.")
    claimed_wickets: Optional[int] = Field(default=None, description="Explicit wickets mentioned in assertion.")
    claimed_overs: Optional[int] = Field(default=None, description="Explicit overs delta mentioned in assertion.")
    claimed_player: Optional[str] = Field(default=None, description="Explicit player name mentioned in assertion.")


class AIExplanationDraft(BaseModel):
    """Structured LLM output prior to independent deterministic verification."""
    model_config = ConfigDict(extra="forbid", frozen=True)

    summary: str = Field(..., min_length=10, max_length=1024, description="High-level interval summary.")
    claims: List[AICandidateClaim] = Field(
        ...,
        min_length=1,
        description="Ordered list of granular assertions with explicit citations.",
    )
